/* V1.6.5 · foco inteligente + mapa/lista bidireccional */
(()=>{
'use strict';
const VERSION='1.6.5', STATE_KEY='cec_territory_official_v150', DRAW_KEY='cec_territory_individual_drawings_v162', LEARN_KEY='cec_territory_focus_v165';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const DATA=window.CongTerritoryOfficialData?.data||{};
const STATIC={
 '1':{'Mz 89c':[54.3,29.6],'Mz 104':[76.2,52.6],'Mz 105':[76.3,42.8],'Mz 106':[81.7,33.3],'Mz 109':[76.9,62.1],'Mz 110':[74.3,71.3],'Mz 110a':[70.7,78.6],'Mz 127a':[19.8,19.4],'Mz 8903':[46.5,27.7]},
 '32':{'Mz 1528':[24.2,39.1],'Mz 1504a':[48,30.5],'Mz 1504b':[72.6,29.5],'Mz 1504c':[48.5,40.9],'Mz 1501':[61.0,48.7],'Mz 1503':[44.5,56.9],'Mz 1433':[81,50],'Mz 1502':[58,69],'Mz 1432':[79,69],'Mz 1431':[76,84]}
};
let requestedKey=null,requestedAt=0,autoBusy=false;
function read(k,f){try{return JSON.parse(localStorage.getItem(k)||'')||f}catch(_){return f}}
function write(k,v){localStorage.setItem(k,JSON.stringify(v))}
function territory(){return String($('#t15Select')?.value||'1')}
function parts(k){const a=String(k||'').split('::');return{item:a[0]||'',side:a[1]||'territorio'}}
function done(n,k){return !!(read(STATE_KEY,{})[n]?.done||{})[k]}
function centroid(points){if(!points?.length)return{x:50,y:50};return points.reduce((a,p)=>({x:a.x+(+p.x||0)/points.length,y:a.y+(+p.y||0)/points.length}),{x:0,y:0})}
function installStyle(){if($('#cecV165Style'))return;const s=document.createElement('style');s.id='cecV165Style';s.textContent=`
#cecV165Guide{position:absolute;inset:0;width:100%;height:100%;z-index:5;pointer-events:none;overflow:visible}#cecV165Guide line{stroke:#ef8b00;stroke-width:2.2;stroke-linecap:round;vector-effect:non-scaling-stroke;filter:drop-shadow(0 0 2px rgba(255,255,255,.9));animation:cecV165Pulse .8s ease-in-out infinite alternate}#cecV165Guide circle{fill:rgba(239,139,0,.13);stroke:#ef8b00;stroke-width:1.4;vector-effect:non-scaling-stroke;animation:cecV165Pulse .8s ease-in-out infinite alternate}@keyframes cecV165Pulse{to{opacity:.35}}
.cec-v165-focus-note{position:absolute;left:50%;top:12px;transform:translateX(-50%);z-index:7;background:#173f52;color:#fff;border-radius:999px;padding:7px 11px;font-size:10px;font-weight:900;box-shadow:0 5px 18px rgba(0,0,0,.18);pointer-events:none;white-space:nowrap}.cec-v165-autook{position:fixed;left:50%;bottom:calc(100px + env(safe-area-inset-bottom));transform:translateX(-50%);z-index:10050;background:#0b6e55;color:#fff;border-radius:999px;padding:9px 13px;font-size:11px;font-weight:900;box-shadow:0 8px 22px rgba(0,0,0,.24);opacity:0;transition:opacity .18s;pointer-events:none}.cec-v165-autook.show{opacity:1}`;document.head.appendChild(s)}
function learned(){return read(LEARN_KEY,{})}
function learnKey(n,k,p){if(!k||!p)return;const all=learned();all[n]=all[n]||{};all[n][k]={x:+p.x.toFixed(2),y:+p.y.toFixed(2),at:new Date().toISOString()};write(LEARN_KEY,all)}
function learnLatest(n){const arr=read(DRAW_KEY,{})[n]||[],st=arr[arr.length-1];if(!st?.points?.length||!st.keys?.length)return;const c=centroid(st.points);st.keys.forEach(k=>learnKey(n,k,c))}
function baseAnchor(n,item){const l=learned()[n]||{};const exact=Object.entries(l).filter(([k])=>parts(k).item===item).map(([,v])=>v);if(exact.length){return{x:exact.reduce((s,v)=>s+v.x,0)/exact.length,y:exact.reduce((s,v)=>s+v.y,0)/exact.length,source:'learned'}}
 const st=STATIC[n]?.[item];if(st)return{x:st[0],y:st[1],source:'static'};
 const d=DATA[n],items=d?.items||[],idx=Math.max(0,items.indexOf(item)),count=Math.max(1,items.length);if(d?.type==='tramos')return{x:50,y:20+idx*(62/Math.max(1,count-1)),source:'fallback'};
 const cols=count>12?3:count>5?2:1,rows=Math.ceil(count/cols),col=idx%cols,row=Math.floor(idx/cols);return{x:cols===1?50:cols===2?(col?68:34):(25+col*25),y:22+row*(62/Math.max(1,rows-1)),source:'fallback'} }
function anchorFor(n,k){const l=learned()[n]?.[k];if(l)return{x:l.x,y:l.y,source:'learned'};const {item,side}=parts(k),b=baseAnchor(n,item),o={N:[0,-5.5],S:[0,5.5],E:[7,0],O:[-7,0],territorio:[0,0]}[side]||[0,0];return{x:Math.max(3,Math.min(97,b.x+o[0])),y:Math.max(3,Math.min(97,b.y+o[1])),source:b.source}}
function guide(k){const stage=$('#cecV162Stage');if(!stage)return;$('#cecV165Guide')?.remove();$('.cec-v165-focus-note',stage)?.remove();const n=territory(),{side}=parts(k),a=anchorFor(n,k),svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.id='cecV165Guide';svg.setAttribute('viewBox','0 0 100 100');if(side==='N'||side==='S'){svg.innerHTML=`<line x1="${a.x-8}" y1="${a.y}" x2="${a.x+8}" y2="${a.y}"/>`}else if(side==='E'||side==='O'){svg.innerHTML=`<line x1="${a.x}" y1="${a.y-7}" x2="${a.x}" y2="${a.y+7}"/>`}else svg.innerHTML=`<circle cx="${a.x}" cy="${a.y}" r="5"/>`;stage.appendChild(svg);const note=document.createElement('div');note.className='cec-v165-focus-note';note.textContent='Área a marcar';stage.appendChild(note)}
function zoomFocus(k){const n=territory(),a=anchorFor(n,k),api=window.CongElCalafateTerritoriosV162;api?.load?.(n);let tries=0;const run=()=>{const vp=$('#cecV162Viewport'),stage=$('#cecV162Stage'),img=$('#cecV162Image');if(!vp||!stage||!img?.naturalWidth){if(tries++<18)return setTimeout(run,120);return}$('#cecV162Fit')?.click();for(let i=0;i<6;i++)$('#cecV162Plus')?.click();guide(k);requestAnimationFrame(()=>{const x=a.x/100*stage.scrollWidth-vp.clientWidth/2,y=a.y/100*stage.scrollHeight-vp.clientHeight/2;vp.scrollTo({left:Math.max(0,x),top:Math.max(0,y),behavior:'smooth'});api?.setDrawing?.(true)})};setTimeout(run,120)}
function toast(msg){let e=$('#cecV165Toast');if(!e){e=document.createElement('div');e.id='cecV165Toast';e.className='cec-v165-autook';document.body.appendChild(e)}e.textContent=msg;e.classList.add('show');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('show'),1800)}
function candidates(n){const d=DATA[n];if(!d)return[];const out=[];if(d.type==='tramos')d.items.forEach(item=>{const k=item+'::territorio',a=anchorFor(n,k);out.push({k,item,side:'territorio',...a})});else d.items.forEach(item=>['N','E','S','O'].forEach(side=>{const k=item+'::'+side,a=anchorFor(n,k);out.push({k,item,side,...a})}));return out}
function strokeShape(st){const pts=st.points||[],c=centroid(pts),xs=pts.map(p=>+p.x),ys=pts.map(p=>+p.y),minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys),w=maxx-minx,h=maxy-miny;let len=0;for(let i=1;i<pts.length;i++)len+=Math.hypot(pts[i].x-pts[i-1].x,pts[i].y-pts[i-1].y);const end=pts.length>1?Math.hypot(pts[0].x-pts.at(-1).x,pts[0].y-pts.at(-1).y):99;return{c,w,h,len,closed:end<Math.max(6,Math.hypot(w,h)*.45)}}
function autoResolve(){if(autoBusy||requestedKey&&Date.now()-requestedAt<2500)return;const r=$('#cecV162Resolve');if(!r?.classList.contains('open'))return;const n=territory(),arr=read(DRAW_KEY,{})[n]||[],st=arr[arr.length-1];if(!st||st.keys?.length||!st.points?.length)return;const sh=strokeShape(st),d=DATA[n];if(!d)return;let keys=[];
 if(d.type!=='tramos'&&sh.closed&&sh.w>8&&sh.h>7){let best=null;for(const item of d.items){const a=baseAnchor(n,item),dist=Math.hypot(a.x-sh.c.x,a.y-sh.c.y);if(!best||dist<best.dist)best={item,dist,source:a.source}}if(best&&best.dist<(best.source==='fallback'?8:16))keys=['N','E','S','O'].map(s=>best.item+'::'+s).filter(k=>!done(n,k));}
 if(!keys.length){let best=null;for(const c of candidates(n)){const dist=Math.hypot(c.x-sh.c.x,c.y-sh.c.y);if(!best||dist<best.dist)best={...c,dist}}if(best&&best.dist<(best.source==='fallback'?7.5:14))keys=[best.k].filter(k=>!done(n,k));}
 if(!keys.length)return;autoBusy=true;let clicked=0;keys.forEach(k=>{const b=$$('[data-v162-key]',r).find(x=>x.dataset.v162Key===k&&!x.disabled);if(b){b.click();clicked++}});if(clicked){setTimeout(()=>{$('#cecV162Apply')?.click();setTimeout(()=>{learnLatest(n);window.CongElCalafateTerritoriosV150?.select?.(n,false);toast(clicked>1?`${clicked} lados marcados en la lista`:'Lado marcado en la lista')},140)},60)}setTimeout(()=>autoBusy=false,500)}
function capture(){window.addEventListener('click',e=>{const b=e.target.closest?.('[data-side-toggle],[data-tramo]');if(!b)return;const n=territory(),k=b.dataset.sideToggle||`${b.dataset.tramo}::territorio`;if(done(n,k))return;requestedKey=k;requestedAt=Date.now();setTimeout(()=>zoomFocus(k),150);setTimeout(()=>{requestedKey=null},5000)},true);
 window.addEventListener('pointerup',e=>{if(e.target?.id==='cecV162Svg'||e.target?.closest?.('#cecV162Svg')){setTimeout(autoResolve,120);setTimeout(()=>learnLatest(territory()),450)}},true);
 document.addEventListener('click',e=>{if(e.target?.id==='cecV162Apply')setTimeout(()=>learnLatest(territory()),180)},true)}
function observe(){const mo=new MutationObserver(()=>{if($('#cecV162Resolve.open'))setTimeout(autoResolve,30)});mo.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['class']})}
installStyle();capture();if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',observe,{once:true});else observe();
window.CongElCalafateTerritoriosV165={version:VERSION,focusKey:zoomFocus,autoResolve,anchors:STATIC};
})();